pub struct Face {
    pub vertices: [usize; 3],
        let mut face = triangle.clone();
        face.vertices = face.vertices.map(|v| representatives[v]);
    for i in 1..snapped.len() {
        if representatives[i] == i && (params.on("keep_unused") || used.contains(&i)) {
            output_map[i] = vertices.len();
            vertices.push(snapped[i]);
        }
    }
    for face in &mut faces { face.vertices = face.vertices.map(|v| output_map[v]); }
pub type Point = [i64; 3];
pub fn normal(face: &Face, vertices: &[Point]) -> Point {
    let [a, b, c] = face.vertices.map(|v| vertices[v]);
    cross(subtract(b, a), subtract(c, a))
}
